package claim

import (
	"fmt"
	"path"
	"strconv"
	"strings"

	"github.com/intentdriven/abcd/internal/gitutil"
)

// Generated files (spc-2610161044461448 step 11; iss-2610152125101468): a
// file the repository declares `linguist-generated` is regenerated by every
// branch that changes what it is generated from, so it never counts as the
// path two reservations share. The declaration is the one every account
// shares: the root .gitattributes on origin's default branch, as this checkout
// last fetched it. A nested .gitattributes, .git/info/attributes and the
// working tree are never read, and reading it is a disk read, never a fetch;
// a file at or below a directory holding its own .gitattributes is never
// generated, since that file could unset the attribute there.
//
// Every misreading leans towards "not generated", so an overlap is still
// refused: an absent file, or no default branch, declares nothing; a file that
// cannot be read, is not a regular file, is past attributesCap or holds a NUL
// byte declares nothing and says why; and a line the reader does not
// understand is skipped, or, when it could unset linguist-generated, voids
// every line before it.

const (
	// attributesCap is the largest .gitattributes abcd reads.
	attributesCap = 256 << 10
	// treeListCap bounds the listing of the files on origin's default branch.
	treeListCap = 32 << 20
	// attrLineMax is git's longest attributes line; a line this long or longer
	// is not understood.
	attrLineMax = 2048
	// generatedAttr is the attribute that declares a file generated.
	generatedAttr = "linguist-generated"
)

// Generated is the set of regular files on origin's default branch, as last
// fetched, that its root .gitattributes declares linguist-generated. A
// directory is never in it, even when every file under it is, nor is a
// symbolic link. The zero value is empty.
type Generated struct{ files map[string]bool }

// Is reports whether p, a repository-relative path, is a generated file.
func (g Generated) Is(p string) bool {
	return len(g.files) > 0 && g.files[path.Clean(p)]
}

// GeneratedFiles reads the generated files from origin's default branch as
// this checkout last fetched it, reading history as stored. The reason is ""
// when the declaration was read, or there is none (no default branch, no
// root .gitattributes); otherwise the set is empty and the reason says why
// generated files were not recognised.
func GeneratedFiles(root string) (Generated, string) {
	ref := originDefault(root)
	if ref == "" {
		return Generated{}, ""
	}
	text, why := rootAttributes(root, ref)
	if why != "" {
		return Generated{}, why
	}
	short := gitutil.ShortRef(ref)
	if why := plainDeclaration(text); why != "" {
		return Generated{}, ".gitattributes on " + short + " " + why
	}
	rules := parseAttributes(text)
	if !rules.any() {
		return Generated{}, ""
	}
	out, err := storedGit(root, treeListCap, "ls-tree", "-r", "-z", "--full-tree", ref)
	if err != nil {
		return Generated{}, fmt.Sprintf("the files on %s could not be listed: %s", gitutil.ShortRef(ref), redacted(err))
	}
	candidates, why := candidatesOf(strings.Split(out, "\x00"))
	if why != "" {
		return Generated{}, short + " " + why
	}
	files, spent := rules.generatedAmong(candidates)
	if spent {
		return Generated{}, fmt.Sprintf(".gitattributes on %s takes too long to match against the files there", short)
	}
	return Generated{files: files}, ""
}

// plainDeclaration is why the root declaration is not plain, "" when it is:
// abcd shares a generated file only on a declaration that is ASCII
// throughout, quotes no pattern and names no macro.
func plainDeclaration(text string) string {
	if !isASCII(text) {
		return "holds a byte outside ASCII"
	}
	for line := range strings.SplitSeq(text, "\n") {
		f := attrFields(line)
		switch {
		case len(f) == 0:
		case strings.HasPrefix(f[0], `"`):
			return "quotes a pattern"
		case strings.HasPrefix(f[0], "[attr]"):
			return "names a macro"
		}
	}
	return ""
}

// isASCII reports whether s holds no byte of 0x80 or above.
func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

// generatedAmong is the paths the declaration makes generated, judged within
// generatedSteps together; spent is true, and the set nil, when the budget
// ran out first.
func (rs attrRules) generatedAmong(paths []string) (map[string]bool, bool) {
	files := map[string]bool{}
	total := generatedSteps
	for _, p := range paths {
		generated, spent := rs.judge(p, &total)
		if spent {
			return nil, true
		}
		if generated {
			files[p] = true
		}
	}
	return files, false
}

// candidatesOf is the files of an ls-tree -r -z listing that may be
// generated: regular files, executable or not, never a symbolic link or a
// submodule, and none at or below a directory holding its own .gitattributes.
// Such a file could unset the attribute there, and only the root one is read.
// The directory and the file's path are compared without regard to ASCII
// case, as git on a case-insensitive checkout compares them, and a file whose
// path is not ASCII is never generated. why, when it is not "", is a
// .gitattributes the listing holds that abcd shares nothing beside: one in a
// directory or under a name outside ASCII, or a second at the root in other
// capitals.
func candidatesOf(entries []string) (candidates []string, why string) {
	nested := &dirTrie{}
	for _, entry := range entries {
		_, p, ok := strings.Cut(entry, "\t")
		if !ok {
			continue
		}
		dir, name := path.Split(p)
		if !strings.EqualFold(name, ".gitattributes") {
			continue
		}
		switch {
		case !isASCII(dir):
			return nil, "holds a .gitattributes in a directory named outside ASCII"
		case !isASCII(name):
			return nil, "holds a .gitattributes named outside ASCII"
		case dir == "" && name != ".gitattributes":
			return nil, "holds a second root .gitattributes in other capitals"
		case dir != "":
			nested.add(asciiLower(strings.TrimSuffix(dir, "/")))
		}
	}
	for _, entry := range entries {
		meta, p, ok := strings.Cut(entry, "\t")
		f := strings.Fields(meta)
		if ok && len(f) == 3 && (f[0] == "100644" || f[0] == "100755") && f[1] == "blob" && isASCII(p) && !nested.holdsAncestor(asciiLower(p)) {
			candidates = append(candidates, p)
		}
	}
	return candidates, ""
}

// dirTrie is a set of directories, one node per path segment, so a path's
// ancestors are looked up in one pass over it.
type dirTrie struct {
	children map[string]*dirTrie
	// end is true when the directory ending at this node is in the set.
	end bool
}

// add puts the directory dir, slash-separated, in the set.
func (t *dirTrie) add(dir string) {
	n := t
	for seg := range strings.SplitSeq(dir, "/") {
		if n.children == nil {
			n.children = map[string]*dirTrie{}
		}
		next := n.children[seg]
		if next == nil {
			next = &dirTrie{}
			n.children[seg] = next
		}
		n = next
	}
	n.end = true
}

// holdsAncestor reports whether a directory in the set holds the file p, at
// any depth, reading p once.
func (t *dirTrie) holdsAncestor(p string) bool {
	n := t
	for {
		i := strings.IndexByte(p, '/')
		if i < 0 || n.children == nil {
			return false
		}
		if n = n.children[p[:i]]; n == nil {
			return false
		}
		if n.end {
			return true
		}
		p = p[i+1:]
	}
}

// asciiLower is s with ASCII capitals lowered, as git folds case.
func asciiLower(s string) string {
	for i := 0; i < len(s); i++ {
		if c := s[i]; c >= 'A' && c <= 'Z' {
			b := []byte(s)
			for j := i; j < len(b); j++ {
				if b[j] >= 'A' && b[j] <= 'Z' {
					b[j] += 'a' - 'A'
				}
			}
			return string(b)
		}
	}
	return s
}

// rootAttributes is the root .gitattributes on ref, "" when there is none,
// with the reason when it is there but was not read.
func rootAttributes(root, ref string) (string, string) {
	short := gitutil.ShortRef(ref)
	out, err := storedGit(root, 4096, "ls-tree", "-l", "-z", "--full-tree", ref, "--", ".gitattributes")
	if err != nil {
		return "", fmt.Sprintf(".gitattributes on %s could not be read: %s", short, redacted(err))
	}
	if out == "" {
		return "", ""
	}
	meta, _, _ := strings.Cut(out, "\t")
	f := strings.Fields(meta)
	if len(f) != 4 || f[0] != "100644" && f[0] != "100755" || f[1] != "blob" || !gitutil.IsFullSHA(f[2]) {
		return "", fmt.Sprintf(".gitattributes on %s is not a regular file", short)
	}
	size, err := strconv.ParseInt(f[3], 10, 64)
	if err != nil {
		return "", fmt.Sprintf(".gitattributes on %s has a size git did not state", short)
	}
	if size > attributesCap {
		return "", fmt.Sprintf(".gitattributes on %s is %d bytes, past the %d KiB abcd reads", short, size, attributesCap>>10)
	}
	text, err := storedGit(root, attributesCap, "cat-file", "blob", f[2])
	if err != nil {
		return "", fmt.Sprintf(".gitattributes on %s could not be read: %s", short, redacted(err))
	}
	if strings.IndexByte(text, 0) >= 0 {
		// git stops reading at a NUL, having applied the lines before it.
		return "", fmt.Sprintf(".gitattributes on %s holds a NUL byte", short)
	}
	return text, ""
}

// attrRule is one line that decides linguist-generated for the paths it
// matches.
type attrRule struct {
	// pat is the glob, its leading slash stripped.
	pat string
	// basename is true for a pattern with no slash, matched against the
	// basename at any depth; otherwise pat is matched against the whole path.
	basename bool
	// generated is the state the line gives: true only for linguist-generated
	// set or =true.
	generated bool
	// prefix and suffix are the literal bytes pat begins and ends with, up to
	// its first and from its last special byte: a subject that does not begin
	// and end with them cannot match, so it is turned away without a match.
	prefix, suffix string
	// fold is true for a line that does not set the attribute: it matches
	// where git's would on either kind of clone, one that ignores case or
	// one that does not, so it unsets at least as far as git's would on any.
	// A line that sets it matches only where git's would on both, so it
	// never sets more than git's would on any clone.
	fold bool
}

// globSpecial reports whether c is a byte wildmatch reads as other than
// itself.
func globSpecial(c byte) bool {
	return c == '*' || c == '?' || c == '[' || c == ']' || c == '\\'
}

// literalEnds is the literal prefix and suffix of pat (attrRule).
func literalEnds(pat string) (prefix, suffix string) {
	i := 0
	for i < len(pat) && !globSpecial(pat[i]) {
		i++
	}
	if i == len(pat) {
		return pat, pat
	}
	j := len(pat)
	for j > 0 && !globSpecial(pat[j-1]) {
		j--
	}
	prefix, suffix = pat[:i], pat[j:]
	// A slash beside a star may be part of "**/" or "/**/", which can match
	// no directory at all, so it is not required.
	if strings.HasPrefix(suffix, "/") {
		suffix = suffix[1:]
	}
	prefix = strings.TrimSuffix(prefix, "/")
	return prefix, suffix
}

// attrRules are the deciding lines in file order: the last that matches a
// path decides it, and a path no line matches is not generated.
type attrRules []attrRule

// generated reports whether the declaration makes the file p generated.
func (rs attrRules) generated(p string) bool {
	generated, _ := rs.judge(p, nil)
	return generated
}

// judge is generated within budgets: matching p against one line may take
// matchSteps, and every match together may take *total when total is not
// nil. A line past its budget makes p not generated, whatever earlier lines
// say, since it might have unset the attribute; spent is true when *total ran
// out, so no later path can be judged either.
func (rs attrRules) judge(p string, total *int) (generated, spent bool) {
	base := p[strings.LastIndexByte(p, '/')+1:]
	for i := len(rs) - 1; i >= 0; i-- {
		subject := p
		if rs[i].basename {
			subject = base
		}
		b := wildBudget{left: matchSteps, fold: rs[i].fold}
		if total != nil && *total < b.left {
			b.left = *total
		}
		start := b.left
		m := wmNoMatch
		if b.take(len(rs[i].prefix)+len(rs[i].suffix)) && b.hasPrefix(subject, rs[i].prefix) && b.hasSuffix(subject, rs[i].suffix) {
			m = dowild(rs[i].pat, subject, &b)
		}
		if total != nil {
			*total -= start - max(b.left, 0)
		}
		if b.left < 0 {
			return false, total != nil && *total <= 0
		}
		if m == wmMatch {
			return rs[i].generated, false
		}
	}
	return false, false
}

// any reports whether some line can make a file generated.
func (rs attrRules) any() bool {
	for _, r := range rs {
		if r.generated {
			return true
		}
	}
	return false
}

// lineKind is what one attributes line is to the reader.
type lineKind int

const (
	// lineIgnored decides nothing: a blank, a comment, a macro definition,
	// a line naming no linguist-generated state, or one git itself ignores
	// (a negated pattern, an invalid attribute name).
	lineIgnored lineKind = iota
	// lineRule decides linguist-generated for the paths it matches.
	lineRule
	// lineVoids is a line git reads but this reader does not understand, and
	// that could unset linguist-generated: every line before it is voided.
	lineVoids
)

// parseAttributes reads the subset of git's gitattributes rules that decide
// linguist-generated.
func parseAttributes(text string) attrRules {
	lines := strings.Split(strings.TrimPrefix(text, "\ufeff"), "\n")
	macros := unsettingMacros(lines)
	var rules attrRules
	for _, line := range lines {
		r, kind := parseAttrLine(line, macros)
		switch kind {
		case lineRule:
			rules = append(rules, r)
		case lineVoids:
			rules = nil
		}
	}
	return rules
}

// attrFields splits a line on git's blanks.
func attrFields(line string) []string {
	return strings.FieldsFunc(line, func(r rune) bool { return r == ' ' || r == '\t' || r == '\r' || r == '\n' })
}

// attrToken is one attribute on a line: its name, and whether it sets
// linguist-generated to generated (no prefix, and no value or =true).
func attrToken(tok string) (name string, set bool) {
	signed := tok[0] == '-' || tok[0] == '!'
	if signed {
		tok = tok[1:]
	}
	name, value, hasValue := strings.Cut(tok, "=")
	return name, !signed && (!hasValue || value == "true")
}

// unsettingMacros are the macros, by name, whose expansion names
// linguist-generated, directly or through another macro. The reader never
// follows a macro: a line naming one decides "not generated", which can only
// share less than git would.
func unsettingMacros(lines []string) map[string]bool {
	defs := map[string][]string{}
	for _, line := range lines {
		f := attrFields(line)
		if len(f) == 0 || !strings.HasPrefix(f[0], "[attr]") {
			continue
		}
		name, attrs := strings.TrimPrefix(f[0], "[attr]"), f[1:]
		if name == "" {
			// A bare [attr] is a pattern to git, never a macro definition.
			continue
		}
		defs[name] = append(defs[name], attrs...)
	}
	touching := map[string]bool{}
	for changed := true; changed; {
		changed = false
		for name, attrs := range defs {
			if touching[name] {
				continue
			}
			for _, a := range attrs {
				if n, _ := attrToken(a); n == generatedAttr || touching[n] {
					touching[name], changed = true, true
					break
				}
			}
		}
	}
	return touching
}

// parseAttrLine reads one line.
func parseAttrLine(line string, macros map[string]bool) (attrRule, lineKind) {
	if len(line) >= attrLineMax {
		return attrRule{}, voidsIf(line, macros)
	}
	f := attrFields(line)
	if len(f) > 0 && f[0] == "[attr]" {
		// git reads a bare [attr] as a pattern, a class of a, t and r, which
		// this reader does not take for one.
		return attrRule{}, voidsIf(line, macros)
	}
	if len(f) == 0 || strings.HasPrefix(f[0], "#") || strings.HasPrefix(f[0], "[attr]") {
		return attrRule{}, lineIgnored
	}
	pat := f[0]
	switch {
	case strings.HasPrefix(pat, `"`):
		// A C-quoted pattern, which git unquotes and this reader does not.
		return attrRule{}, voidsIf(line, macros)
	case strings.HasPrefix(pat, "!"):
		// git ignores a negative pattern in an attributes file.
		return attrRule{}, lineIgnored
	}
	decides, generated, macro := false, false, false
	for _, tok := range f[1:] {
		name, set := attrToken(tok)
		if !validAttrName(name) {
			// git ignores the whole line over one invalid attribute name.
			return attrRule{}, lineIgnored
		}
		if macros[name] {
			macro = true
		}
		if name == generatedAttr {
			// The last token naming it on the line wins, as in git.
			decides, generated = true, set
		}
	}
	if macro {
		// A macro naming linguist-generated decides "not generated",
		// whatever else the line says.
		decides, generated = true, false
	}
	if !decides {
		return attrRule{}, lineIgnored
	}
	if strings.HasSuffix(pat, "/") {
		// A pattern naming a directory matches no file.
		return attrRule{}, lineIgnored
	}
	basename := !strings.Contains(pat, "/")
	pat = strings.TrimPrefix(pat, "/")
	if pat == "" || !globSupported(pat) {
		return attrRule{}, voidsIf(line, macros)
	}
	prefix, suffix := literalEnds(pat)
	return attrRule{pat: pat, basename: basename, generated: generated, prefix: prefix, suffix: suffix, fold: !generated}, lineRule
}

// voidsIf is the kind of a line the reader does not understand: it voids the
// lines before it when it could unset linguist-generated (it names the
// attribute other than as set, or names an unsetting macro), and is ignored
// otherwise, since ignoring a line that sets it only shares less.
func voidsIf(line string, macros map[string]bool) lineKind {
	for _, tok := range attrFields(line) {
		if strings.Contains(tok, generatedAttr) && tok != generatedAttr && tok != generatedAttr+"=true" {
			return lineVoids
		}
		for m := range macros {
			if strings.Contains(tok, m) {
				return lineVoids
			}
		}
	}
	return lineIgnored
}

// validAttrName is git's rule for an attribute name: letters, digits, '-',
// '.' and '_', not starting with '-', and not reserved (builtin_).
func validAttrName(name string) bool {
	if name == "" || name[0] == '-' || strings.HasPrefix(name, "builtin_") {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		if !(c == '-' || c == '.' || c == '_' || c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z') {
			return false
		}
	}
	return true
}

// globSupported reports whether the reader understands pat: no POSIX class,
// every bracket expression closed, and no trailing lone backslash.
func globSupported(pat string) bool {
	if strings.Contains(pat, "[:") {
		return false
	}
	for i := 0; i < len(pat); i++ {
		switch pat[i] {
		case '\\':
			if i+1 >= len(pat) {
				return false
			}
			i++
		case '[':
			j := i + 1
			if j < len(pat) && (pat[j] == '!' || pat[j] == '^') {
				j++
			}
			// The first character of a class may be ']' itself.
			first := true
			for ; j < len(pat) && (first || pat[j] != ']'); j++ {
				first = false
				if pat[j] == '\\' {
					j++
				}
			}
			if j >= len(pat) {
				return false
			}
			i = j
		}
	}
	return true
}

// matchSteps bounds the steps matching one path against one line takes.
// Both budgets are variables, so a test can measure their edge.
var matchSteps = 1_000_000

// generatedSteps bounds the matching GeneratedFiles does over every file
// together; past it the declaration declares nothing, and says why. A step
// costs about a nanosecond: an ordinary tree of 150,000 files against 50
// lines takes about 3e8 of them (0.22 to 0.56 s, TestALargeOrdinaryTreeFitsTheBudget),
// and the worst case, a declaration that spends the whole budget
// (TestTheBudgetBoundsWallTimeOverLongLiterals), stops after about 0.6 to
// 0.8 s on the machine this was sized on and up to about 1.5 s measured on
// another; measured 2026-10-17, under load.
var generatedSteps = 500_000_000

// wildBudget is the steps a match has left: each call, each byte of the
// pattern or the text compared, skipped or scanned, and each try of a star
// spends one, so the steps bound the time a match takes; a match past it
// answers wmAbortAll.
type wildBudget struct {
	left int
	// fold is true when bytes compare without regard to ASCII case
	// (attrRule.fold).
	fold bool
}

// same reports whether the text byte t matches the pattern byte c.
func (b *wildBudget) same(t, c byte) bool {
	return t == c || b.fold && lowerByte(t) == lowerByte(c)
}

// hasPrefix and hasSuffix are strings.HasPrefix and HasSuffix, folding when
// b folds.
func (b *wildBudget) hasPrefix(s, prefix string) bool {
	return len(s) >= len(prefix) && b.equal(s[:len(prefix)], prefix)
}

func (b *wildBudget) hasSuffix(s, suffix string) bool {
	return len(s) >= len(suffix) && b.equal(s[len(s)-len(suffix):], suffix)
}

func (b *wildBudget) equal(x, y string) bool {
	if !b.fold {
		return x == y
	}
	for i := 0; i < len(x); i++ {
		if lowerByte(x[i]) != lowerByte(y[i]) {
			return false
		}
	}
	return true
}

// lowerByte and upperByte change an ASCII letter's case, as git folds it.
func lowerByte(c byte) byte {
	if c >= 'A' && c <= 'Z' {
		return c + 'a' - 'A'
	}
	return c
}

func upperByte(c byte) byte {
	if c >= 'a' && c <= 'z' {
		return c - ('a' - 'A')
	}
	return c
}

// spend takes one step, reporting whether the budget still holds.
func (b *wildBudget) spend() bool {
	b.left--
	return b.left >= 0
}

// take takes n steps, one for each byte a scan reads.
func (b *wildBudget) take(n int) bool {
	b.left -= n
	return b.left >= 0
}

// scanSlash is strings.IndexByte(s, '/'), charged one step per byte read.
func scanSlash(s string, b *wildBudget) (int, bool) {
	i := strings.IndexByte(s, '/')
	n := len(s)
	if i >= 0 {
		n = i + 1
	}
	return i, b.take(n)
}

// wildmatch's answers, as git's wildmatch.c gives them.
const (
	wmMatch = iota
	wmNoMatch
	wmAbortAll
	wmAbortToStarStar
)

// dowild is git's wildmatch with WM_PATHNAME, case-sensitive: '*', '?' and a
// class never match a slash, and "**" matches across slashes only between
// slashes (a leading "**/", a trailing "/**", a middle "/**/"). A basename
// holds no slash, so the same matcher serves a pattern with none. Every call,
// every byte compared, skipped or scanned and every try of a star spends from
// b, and a match past it is wmAbortAll.
func dowild(p, text string, b *wildBudget) int {
	if !b.spend() {
		return wmAbortAll
	}
	ti := 0
	for pi := 0; pi < len(p); pi, ti = pi+1, ti+1 {
		if !b.spend() {
			return wmAbortAll
		}
		pch := p[pi]
		if ti >= len(text) && pch != '*' {
			return wmAbortAll
		}
		var tch byte
		if ti < len(text) {
			tch = text[ti]
		}
		switch pch {
		case '\\':
			// A literal match with the next character.
			// git ignoring case compares the text byte lowered with the
			// escaped byte as written.
			pi++
			if pi >= len(p) {
				return wmNoMatch
			}
			if c := p[pi]; b.fold && !b.same(tch, c) || !b.fold && (tch != c || lowerByte(tch) != c) {
				return wmNoMatch
			}
		case '?':
			if tch == '/' {
				return wmNoMatch
			}
		case '*':
			matchSlash := false
			pi++
			if pi < len(p) && p[pi] == '*' {
				prev := pi - 2
				for pi < len(p) && p[pi] == '*' {
					if !b.spend() {
						return wmAbortAll
					}
					pi++
				}
				if (prev < 0 || p[prev] == '/') &&
					(pi == len(p) || p[pi] == '/' || p[pi] == '\\' && pi+1 < len(p) && p[pi+1] == '/') {
					// "**/" may match no directory at all.
					if pi < len(p) && p[pi] == '/' && dowild(p[pi+1:], text[ti:], b) == wmMatch {
						return wmMatch
					}
					matchSlash = true
				}
			}
			if pi == len(p) {
				// A trailing "**" matches everything; a trailing "*" only
				// what holds no slash.
				if !matchSlash {
					slash, ok := scanSlash(text[ti:], b)
					if !ok {
						return wmAbortAll
					}
					if slash >= 0 {
						return wmNoMatch
					}
				}
				return wmMatch
			}
			if !matchSlash && p[pi] == '/' {
				// One '*' then a slash matches the rest of this directory.
				slash, ok := scanSlash(text[ti:], b)
				if !ok {
					return wmAbortAll
				}
				if slash < 0 {
					return wmNoMatch
				}
				ti += slash
				continue
			}
			for ti < len(text) {
				if !b.spend() {
					return wmAbortAll
				}
				if c := p[pi]; c != '*' && c != '?' && c != '[' && c != '\\' {
					// A literal after the star: skip to its next occurrence.
					for ti < len(text) && (matchSlash || text[ti] != '/') && !b.same(text[ti], c) {
						if !b.spend() {
							return wmAbortAll
						}
						ti++
					}
					if ti >= len(text) || !b.same(text[ti], c) {
						if matchSlash {
							return wmAbortAll
						}
						return wmAbortToStarStar
					}
				}
				if m := dowild(p[pi:], text[ti:], b); m != wmNoMatch {
					if !matchSlash || m != wmAbortToStarStar {
						return m
					}
				} else if !matchSlash && text[ti] == '/' {
					return wmAbortToStarStar
				}
				ti++
			}
			return wmAbortAll
		case '[':
			pi++
			if pi >= len(p) {
				return wmAbortAll
			}
			c := p[pi]
			negated := c == '!' || c == '^'
			if negated {
				pi++
				if pi >= len(p) {
					return wmAbortAll
				}
				c = p[pi]
			}
			// The class is judged as git judges it case-sensitively (exact) and
			// as git judges it ignoring case (folded: the text byte lowered,
			// and a range also tried with it raised). A folding line matches
			// when either does, so it matches at least where git's would on
			// either kind of clone; any other line only when both do, so it
			// matches no more than git's would on either.
			lt := lowerByte(tch)
			var exact, folded bool
			var prev byte
			for {
				if !b.spend() {
					return wmAbortAll
				}
				switch {
				case c == '\\':
					pi++
					if pi >= len(p) {
						return wmAbortAll
					}
					c = p[pi]
					exact, folded = exact || tch == c, folded || lt == c
				case c == '-' && prev != 0 && pi+1 < len(p) && p[pi+1] != ']':
					pi++
					c = p[pi]
					if c == '\\' {
						pi++
						if pi >= len(p) {
							return wmAbortAll
						}
						c = p[pi]
					}
					in := func(x byte) bool { return x >= prev && x <= c }
					exact, folded = exact || in(tch), folded || in(lt) || in(upperByte(lt))
					c = 0
				case c == '[' && pi+1 < len(p) && p[pi+1] == ':':
					// A POSIX class, which globSupported refuses before here.
					return wmAbortAll
				default:
					exact, folded = exact || tch == c, folded || lt == c
				}
				prev = c
				pi++
				if pi >= len(p) {
					return wmAbortAll
				}
				if c = p[pi]; c == ']' {
					break
				}
			}
			matched := exact != negated && folded != negated
			if b.fold {
				matched = exact != negated || folded != negated
			}
			if !matched || tch == '/' {
				return wmNoMatch
			}
		default:
			if !b.same(tch, pch) {
				return wmNoMatch
			}
		}
	}
	if ti < len(text) {
		return wmNoMatch
	}
	return wmMatch
}
